package payroll;
import com.sun.net.httpserver.*;
import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets; import java.nio.file.*;
import java.time.*; import java.util.*; import java.util.concurrent.*;
public class Main {
static final int PORT = Integer.parseInt(System.getenv().getOrDefault("PORT", "10000")); 
static final Path ROOT = Paths.get("").toAbsolutePath();
static final Path WEB = ROOT.resolve("web");
static final Path DATA = ROOT.resolve("data");
 static final Map<String,S> sessions=new ConcurrentHashMap<>();
 static void write(Path p,String s)throws IOException{if(!Files.exists(p))Files.writeString(p,s);}
 public static void main(String[]z)throws Exception{
  Files.createDirectories(DATA); write(DATA.resolve("employees.csv"),"id,name,department,designation,email,phone,basic,allowances,bonusRate\nE1001,Aarav Sharma,Engineering,Developer,aarav@example.com,9000000001,35000,8000,15\nE1002,Priya Patel,HR,HR Executive,priya@example.com,9000000002,30000,7000,10\nE1003,Rohan Mehta,Operations,Manager,rohan@example.com,9000000003,50000,12000,20\n");
  write(DATA.resolve("attendance.csv"),"employeeId,date,status\n");write(DATA.resolve("leaves.csv"),"id,employeeId,from,to,reason,status\n");write(DATA.resolve("payroll.csv"),"month,id,name,basic,allowances,bonus,deductions,net\n");
  HttpServer h=HttpServer.create(new InetSocketAddress("0.0.0.0",PORT),0);h.createContext("/api/",Main::api);h.createContext("/",Main::staticFile);h.setExecutor(Executors.newCachedThreadPool());h.start();
  System.out.println("Smart Payroll running at http://0.0.0.0:"+PORT);System.out.println("Admin admin/admin123 | Employee employee/E1001");System.out.println("Keep this process running.");
 }
 static class S{String role,name,id;S(String r,String n,String i){role=r;name=n;id=i;}}
 static class E{String[]a;E(String[]x){a=x;}double basic(){return d(6);}double allow(){return d(7);}double rate(){return d(8);}double bonus(){return basic()*rate()/100;}double gross(){return basic()+allow()+bonus();}double tax(){return gross()*.05;}double net(){return gross()-tax();}double d(int i){return Double.parseDouble(a[i]);}String json(){return "{\"id\":"+q(a[0])+",\"name\":"+q(a[1])+",\"department\":"+q(a[2])+",\"designation\":"+q(a[3])+",\"email\":"+q(a[4])+",\"phone\":"+q(a[5])+",\"basic\":"+basic()+",\"allowances\":"+allow()+",\"bonusRate\":"+rate()+",\"bonus\":"+bonus()+",\"gross\":"+gross()+",\"tax\":"+tax()+",\"net\":"+net()+"}";}String csv(){return String.join(",",a);}}
 static String q(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ")+"\"";}
 static String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ");}
 static Map<String,String> params(HttpExchange x)throws Exception{String r=x.getRequestMethod().equals("GET")?x.getRequestURI().getRawQuery():new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8);Map<String,String>m=new HashMap<>();if(r!=null)for(String p:r.split("&")){String[]a=p.split("=",2);m.put(URLDecoder.decode(a[0],"UTF-8"),a.length>1?URLDecoder.decode(a[1],"UTF-8"):"");}return m;}
 static String tok(HttpExchange x){String a=x.getRequestHeaders().getFirst("Authorization");return a!=null&&a.startsWith("Bearer ")?a.substring(7):"";}
 static S auth(HttpExchange x){return sessions.get(tok(x));}
 static void send(HttpExchange x,int code,String s)throws IOException{byte[]b=s.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.sendResponseHeaders(code,b.length);x.getResponseBody().write(b);x.close();}
 static List<String> lines(String f)throws IOException{return Files.readAllLines(DATA.resolve(f));}
 static void save(String f,List<String> l)throws IOException{Files.write(DATA.resolve(f),l);}
 static List<E> employees()throws IOException{List<E>r=new ArrayList<>();for(String l:lines("employees.csv"))if(!l.startsWith("id,")&&!l.isBlank())r.add(new E(l.split(",",-1)));return r;}
 static String listEmployees(String only)throws IOException{StringBuilder b=new StringBuilder("[");boolean f=true;for(E e:employees())if(only==null||e.a[0].equals(only)){if(!f)b.append(",");f=false;b.append(e.json());}return b.append("]").toString();}
 static String required(Map<String,String>p,String k){String v=p.getOrDefault(k,"").trim();if(v.isEmpty())throw new IllegalArgumentException(k+" is required");return v;}
 static void admin(S s){if(!s.role.equals("ADMIN"))throw new SecurityException();}
 static void api(HttpExchange x)throws IOException{try{
  String path=x.getRequestURI().getPath(),method=x.getRequestMethod();Map<String,String>p=params(x);
  if(path.equals("/api/login")&&method.equals("POST")){String u=p.getOrDefault("username",""),pw=p.getOrDefault("password","");S s=null;if(u.equals("admin")&&pw.equals("admin123"))s=new S("ADMIN","Administrator","ADMIN");if(u.equals("employee")&&pw.equals("E1001"))s=new S("EMPLOYEE","Aarav Sharma","E1001");if(u.equals("employee2")&&pw.equals("E1002"))s=new S("EMPLOYEE","Priya Patel","E1002");if(s==null){send(x,401,"{\"error\":\"Invalid login\"}");return;}String t=UUID.randomUUID().toString();sessions.put(t,s);send(x,200,"{\"token\":"+q(t)+",\"role\":"+q(s.role)+",\"name\":"+q(s.name)+",\"employeeId\":"+q(s.id)+"}");return;}
  if(path.equals("/api/logout")){sessions.remove(tok(x));send(x,200,"{\"ok\":true}");return;}
  S s=auth(x);if(s==null){send(x,401,"{\"error\":\"Please log in\"}");return;}
  if(path.equals("/api/employees")&&method.equals("GET")){send(x,200,listEmployees(s.role.equals("ADMIN")?null:s.id));return;}
  if(path.equals("/api/employees")&&method.equals("POST")){admin(s);String[]a={required(p,"id"),required(p,"name"),required(p,"department"),required(p,"designation"),p.getOrDefault("email",""),p.getOrDefault("phone",""),required(p,"basic"),p.getOrDefault("allowances","0"),p.getOrDefault("bonusRate","0")};double basic=Double.parseDouble(a[6]),rate=Double.parseDouble(a[8]);if(basic<=0||rate<0||rate>100)throw new IllegalArgumentException("Invalid salary or bonus rate");for(E e:employees())if(e.a[0].equalsIgnoreCase(a[0]))throw new IllegalArgumentException("Duplicate employee ID");Files.writeString(DATA.resolve("employees.csv"),String.join(",",a)+"\n",StandardOpenOption.APPEND);send(x,200,"{\"ok\":true}");return;}
  if(path.startsWith("/api/employees/")&&method.equals("DELETE")){admin(s);String id=path.substring(15);List<String>ls=lines("employees.csv");ls.removeIf(l->l.startsWith(id+",")&&!l.startsWith("id,"));save("employees.csv",ls);send(x,200,"{\"ok\":true}");return;}
  if(path.equals("/api/attendance")&&method.equals("GET")){String id=s.role.equals("ADMIN")?p.getOrDefault("employeeId",""):s.id;StringBuilder b=new StringBuilder("[");boolean f=true;for(String l:lines("attendance.csv")){String[]a=l.split(",",-1);if(a.length<3||a[0].equals("employeeId")||(!id.isEmpty()&&!a[0].equals(id)))continue;if(!f)b.append(",");f=false;b.append("{\"employeeId\":").append(q(a[0])).append(",\"date\":").append(q(a[1])).append(",\"status\":").append(q(a[2])).append("}");}send(x,200,b.append("]").toString());return;}
  if(path.equals("/api/attendance")&&method.equals("POST")){admin(s);String id=required(p,"employeeId"),date=required(p,"date"),st=required(p,"status");LocalDate.parse(date);if(!Arrays.asList("Present","Absent","Half Day","Work From Home").contains(st))throw new IllegalArgumentException("Invalid status");Files.writeString(DATA.resolve("attendance.csv"),id+","+date+","+st+"\n",StandardOpenOption.APPEND);send(x,200,"{\"ok\":true}");return;}
  if(path.equals("/api/leaves")&&method.equals("GET")){StringBuilder b=new StringBuilder("[");boolean f=true;for(String l:lines("leaves.csv")){String[]a=l.split(",",-1);if(a.length<6||a[0].equals("id")||(!s.role.equals("ADMIN")&&!a[1].equals(s.id)))continue;if(!f)b.append(",");f=false;b.append("{\"id\":").append(q(a[0])).append(",\"employeeId\":").append(q(a[1])).append(",\"fromDate\":").append(q(a[2])).append(",\"toDate\":").append(q(a[3])).append(",\"reason\":").append(q(a[4])).append(",\"status\":").append(q(a[5])).append("}");}send(x,200,b.append("]").toString());return;}
  if(path.equals("/api/leaves")&&method.equals("POST")){if(s.role.equals("ADMIN"))throw new IllegalArgumentException("Employee login required");String from=required(p,"fromDate"),to=required(p,"toDate"),reason=required(p,"reason").replace(","," ");if(LocalDate.parse(to).isBefore(LocalDate.parse(from)))throw new IllegalArgumentException("Invalid date range");Files.writeString(DATA.resolve("leaves.csv"),UUID.randomUUID().toString().substring(0,8)+","+s.id+","+from+","+to+","+reason+",Pending\n",StandardOpenOption.APPEND);send(x,200,"{\"ok\":true}");return;}
  if(path.startsWith("/api/leaves/")&&path.endsWith("/decision")&&method.equals("POST")){admin(s);String id=path.substring(12,path.length()-9),status=required(p,"status");if(!Arrays.asList("Approved","Rejected").contains(status))throw new IllegalArgumentException("Invalid decision");List<String>ls=lines("leaves.csv");for(int i=1;i<ls.size();i++){String[]a=ls.get(i).split(",",-1);if(a[0].equals(id)&&a.length>=6){a[5]=status;ls.set(i,String.join(",",a));}}save("leaves.csv",ls);send(x,200,"{\"ok\":true}");return;}
  if(path.equals("/api/payroll")&&method.equals("GET")){String id=s.role.equals("ADMIN")?p.getOrDefault("employeeId",""):s.id;StringBuilder b=new StringBuilder("[");boolean f=true;for(String l:lines("payroll.csv")){String[]a=l.split(",",-1);if(a.length<8||a[0].equals("month")||(!id.isEmpty()&&!a[1].equals(id)))continue;if(!f)b.append(",");f=false;b.append("{\"month\":").append(q(a[0])).append(",\"employeeId\":").append(q(a[1])).append(",\"name\":").append(q(a[2])).append(",\"basic\":").append(a[3]).append(",\"allowances\":").append(a[4]).append(",\"bonus\":").append(a[5]).append(",\"deductions\":").append(a[6]).append(",\"net\":").append(a[7]).append("}");}send(x,200,b.append("]").toString());return;}
  if(path.equals("/api/payroll/run")&&method.equals("POST")){admin(s);String month=required(p,"month");YearMonth.parse(month);List<String>ls=lines("payroll.csv");for(E e:employees()){double absent=0,seen=0;for(String a:lines("attendance.csv")){String[]v=a.split(",",-1);if(v.length>=3&&v[0].equals(e.a[0])&&v[1].startsWith(month)){seen++;if(v[2].equals("Absent"))absent++;}}double deduction=e.tax()+(seen>0?e.basic()*Math.min(1,absent/seen):0);ls.add(month+","+e.a[0]+","+e.a[1]+","+e.basic()+","+e.allow()+","+e.bonus()+","+deduction+","+(e.gross()-deduction));}save("payroll.csv",ls);send(x,200,"{\"ok\":true}");return;}
  if(path.equals("/api/reports")){admin(s);int n=employees().size(),att=lines("attendance.csv").size()-1,leave=lines("leaves.csv").size()-1,pay=lines("payroll.csv").size()-1;double gross=0;for(E e:employees())gross+=e.gross();send(x,200,"{\"employeeCount\":"+n+",\"monthlyGross\":"+gross+",\"attendanceRecords\":"+att+",\"leaveRequests\":"+leave+",\"payrollRuns\":"+pay+"}");return;}
  send(x,404,"{\"error\":\"Endpoint not found\"}");
 }catch(SecurityException e){send(x,403,"{\"error\":\"Admin permission required\"}");}catch(Exception e){send(x,400,"{\"error\":\""+esc(e.getMessage()==null?"Request failed":e.getMessage())+"\"}");}}
 static void staticFile(HttpExchange x)throws IOException{String p=x.getRequestURI().getPath();if(p.equals("/"))p="/index.html";Path f=WEB.resolve(p.substring(1)).normalize();if(!f.startsWith(WEB)||!Files.exists(f)||Files.isDirectory(f)){send(x,404,"not found");return;}String n=f.toString();x.getResponseHeaders().set("Content-Type",n.endsWith(".css")?"text/css; charset=utf-8":n.endsWith(".js")?"application/javascript; charset=utf-8":"text/html; charset=utf-8");byte[]b=Files.readAllBytes(f);x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();}
}
